/**
 * Embeds the pdf.js library + worker into a generated JS module so the
 * in-app PDF viewer works fully offline and never loads code from the network.
 * Runs automatically on `npm install` (postinstall).
 */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const buildDir = path.join(root, 'node_modules', 'pdfjs-dist', 'legacy', 'build');
const outFile = path.join(root, 'src', 'viewer', 'pdfjsSource.generated.js');

function read(name) {
  return fs.readFileSync(path.join(buildDir, name), 'utf8');
}

// JSON-encode, and break "</script" so the source can sit inside an inline <script>.
const encode = (src) => JSON.stringify(src).replace(/<\//g, '<\\/');

try {
  const lib = read('pdf.min.mjs');
  const worker = read('pdf.worker.min.mjs');
  const version = require(path.join(root, 'node_modules', 'pdfjs-dist', 'package.json')).version;
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  fs.writeFileSync(
    outFile,
    `// AUTO-GENERATED by scripts/bundle-pdfjs.js from pdfjs-dist@${version}. Do not edit.\n` +
      `export const PDFJS_VERSION = ${JSON.stringify(version)};\n` +
      `export const PDFJS_LIB = ${encode(lib)};\n` +
      `export const PDFJS_WORKER = ${encode(worker)};\n`,
  );
  console.log(`pdf.js ${version} embedded (${Math.round((lib.length + worker.length) / 1024)} KB)`);
} catch (e) {
  console.warn('[bundle-pdfjs] skipped:', e.message);
}
